static inline void pors_precomp_binom_get(pors_u256 *out,
                                             uint32_t n,
                                             uint32_t r)
{
    uint32_t base;
    uint32_t block;
    uint32_t row;
    uint32_t off;
    uint32_t len;

    if (r > n || r > SPX_PORS_FP_K || n > SPX_PORS_FP_T) {
        pors_u256_zero(out);
        return;
    }
    if (r == 0u) {
        pors_u256_set_u64(out, 1u);
        return;
    }
    if (r == 1u) {
        pors_u256_set_u64(out, n);
        return;
    }

    base = (n / PORS_BINOM_STRIDE) * PORS_BINOM_STRIDE;
    if (base < r) {
        base = r;
        pors_u256_set_u64(out, 1u);
    } else {
        block = base / PORS_BINOM_STRIDE;
        switch (r) {
        case 2u:
            row = block - 1u;
            off = pors_binom_r2_offsets[row];
            len = pors_binom_r2_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r2_data + off, len);
            break;
        case 3u:
            row = block - 1u;
            off = pors_binom_r3_offsets[row];
            len = pors_binom_r3_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r3_data + off, len);
            break;
        case 4u:
            row = block - 1u;
            off = pors_binom_r4_offsets[row];
            len = pors_binom_r4_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r4_data + off, len);
            break;
        case 5u:
            row = block - 1u;
            off = pors_binom_r5_offsets[row];
            len = pors_binom_r5_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r5_data + off, len);
            break;
        case 6u:
            row = block - 1u;
            off = pors_binom_r6_offsets[row];
            len = pors_binom_r6_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r6_data + off, len);
            break;
        case 7u:
            row = block - 1u;
            off = pors_binom_r7_offsets[row];
            len = pors_binom_r7_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r7_data + off, len);
            break;
        case 8u:
            row = block - 1u;
            off = pors_binom_r8_offsets[row];
            len = pors_binom_r8_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r8_data + off, len);
            break;
        case 9u:
            row = block - 2u;
            off = pors_binom_r9_offsets[row];
            len = pors_binom_r9_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r9_data + off, len);
            break;
        case 10u:
            row = block - 2u;
            off = pors_binom_r10_offsets[row];
            len = pors_binom_r10_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r10_data + off, len);
            break;
        case 11u:
            row = block - 2u;
            off = pors_binom_r11_offsets[row];
            len = pors_binom_r11_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r11_data + off, len);
            break;
        case 12u:
            row = block - 2u;
            off = pors_binom_r12_offsets[row];
            len = pors_binom_r12_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r12_data + off, len);
            break;
        case 13u:
            row = block - 2u;
            off = pors_binom_r13_offsets[row];
            len = pors_binom_r13_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r13_data + off, len);
            break;
        case 14u:
            row = block - 2u;
            off = pors_binom_r14_offsets[row];
            len = pors_binom_r14_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r14_data + off, len);
            break;
        case 15u:
            row = block - 2u;
            off = pors_binom_r15_offsets[row];
            len = pors_binom_r15_offsets[row + 1u] - off;
            pors_u256_load_limbs(out, pors_binom_r15_data + off, len);
            break;
        default:
            pors_u256_zero(out);
            return;
        }
    }

    for (uint32_t m = base; m < n; m++) {
        pors_precomp_step_binom_up(out, m, r);
    }
}

